def _signed_batch_result(
    status: str,
    payload: dict,
    need: object,
    fork: object,
) -> dict:
    """Assemble a result dict in the fixed result key order."""
    return {
        STATUS: status,
        SB_SESSION: payload[SB_SESSION],
        NEXT: payload[NEXT],
        COMPLETE: payload[COMPLETE],
        NEED: need,
        STATUS_FORK: fork,
    }
